/* ===================== BÀI 23 · LED, buzzer và driver tải ===================== */
/* Bài 23 · LED, buzzer và driver tải (AMTS-EMB-001-M06-L03, MC51-023) — sinh bởi tools/author/mcu8051/l23.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR23=[{"label":"Ví dụ: Lớp driver ẩn cực tính của LED","code":"; Ví dụ 1: lớp driver - chỉ XUAT biết LED tích cực mức thấp\n; 30H: bit = 1 nghĩa là LED đó cần SÁNG (logic, không phải mức)\n        ORG     0000H\n        MOV     30H,#05H                ; logic: LED0 và LED2 sáng\n        ACALL   XUAT                    ; tầng driver đổi logic -> mức chân\n        SJMP    $\nXUAT:   MOV     A,30H\n        CPL     A                       ; tích cực mức thấp: 1 -> chân 0\n        MOV     P1,A\n        RET\n        END\n","note":"Phần logic chỉ ghi 30H = 05H (bật LED0, LED2). Chương trình con XUAT là nơi duy nhất biết LED tích cực mức thấp: đảo rồi ghi P1 = FAH. Theo dõi ngăn xếp khi ACALL/RET: địa chỉ trở về 0005H nằm ở 08H–09H. Tổng 9 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Còi thụ động 2 kHz bằng vòng trễ","code":"; Ví dụ 2: còi thụ động 2 kHz ở P1.0 (qua transistor)\n; Nửa chu kỳ = 250 chu kỳ máy = 250 µs ở 12 MHz.\n        ORG     0000H\n        MOV     R7,#8                   ; 8 nửa chu kỳ = 4 chu kỳ sóng\nNUA:    MOV     R6,#123                 ; 1\n        DJNZ    R6,$                    ; 123 x 2 = 246\n        CPL     P1.0                    ; 1: đảo chân còi\n        DJNZ    R7,NUA                  ; 2 -> 1 + 246 + 1 + 2 = 250\n        SJMP    $\n        END\n","note":"Mỗi vòng NUA đúng 250 chu kỳ máy giữa hai lần CPL P1.0: nửa chu kỳ 250 µs, 2 kHz ở 12 MHz. Mở Đồ thị thời gian, khung 2 000 CK, để thấy sóng vuông. Đổi Thạch anh sang 11,0592 MHz rồi chạy lại: tổng ≈ 2 171,22 µs, tần số tụt còn khoảng 1 843 Hz.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Tải bật trong lúc khởi động","code":"; Bẫy 3: driver tích cực mức CAO - tải bật trong lúc khởi động\n; Đèn ở đây tượng trưng TẢI: sáng khi chân = 1 (NPN + kéo lên).\n        ORG     0000H\n        MOV     R7,#250                 ; việc khởi động khác mất thời gian\n        DJNZ    R7,$                    ; 500 chu kỳ\n        CLR     P1.1                    ; giờ mới tắt tải ở P1.1\n        SJMP    $\n        END\n","note":"Đèn ở ví dụ này tượng trưng tải tích cực mức cao (NPN có kéo lên): sau reset chân = 1 nên CẢ 8 tải bật ngay, kéo dài 501 chu kỳ máy tới khi CLR P1.1 chạy. Với rơ-le hay động cơ, đó là một lần đóng ngoài ý muốn mỗi khi cấp điện.","dev":{"led":{"activeLow":false}},"fosc":12000000},{"label":"Ví dụ: Mặt nạ cực tính cho nhiều tải","code":"; Ví dụ 4: mặt nạ cực tính cho các tải khác loại trên P1\n; P1.0-3 LED, P1.4 còi PNP: mức 0 = bật; P1.5 NPN: mức 1 = bật\n        ORG     0000H\n        MOV     30H,#31H                ; logic: LED0, còi, tải P1.5 bật\n        MOV     A,30H\n        XRL     A,#0DFH                 ; mặt nạ: bit 1 = tích cực mức thấp\n        MOV     P1,A                    ; chân = logic XOR mặt nạ\n        SJMP    $\n        END\n","note":"Logic 31H = LED0, còi P1.4 và tải P1.5 cùng bật. Mặt nạ DFH = 1101 1111B: chỉ P1.5 tích cực mức cao. P1 = 31H XOR DFH = EEH: chân 0 ở P1.0, P1.4 (bật) và chân 1 ở P1.5 (bật). Đoán trước: logic 00H cho P1 bằng bao nhiêu? (DFH — mọi tải tắt.)","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Ghi cả cổng làm tắt còi","code":"; Lỗi 5: phần LED ghi cả cổng P1, làm tắt còi ở P1.7\n; Còi P1.7 qua PNP: chân 0 = kêu.\n        ORG     0000H\n        CLR     P1.7                    ; phần còi: bật còi\n        MOV     P1,#0FEH                ; phần LED: chỉ muốn bật LED0\n        SJMP    $                       ; P1.7 = 1: còi đã tắt!\n        END\n","note":"Phần còi bật còi (CLR P1.7 → P1 = 7FH), rồi phần LED ghi cả cổng MOV P1,#0FEH → P1 = FEH: còi tắt dù không ai muốn. Sửa: phần LED chỉ đụng bit của mình bằng CLR P1.0 hoặc ANL P1,#0FEH.","dev":{"led":true},"fosc":12000000}];
const sim23=makeSim51(document.getElementById("m51-l23"),{id:"s23",presets:PR23,ram:256});
makeEx51(document.getElementById("ex-l23"),"l23",[{"t":"Mặt nạ cực tính của một bo khác","d":"<p>Một bo khác nối các tải trên P1 như sau: <code>P1.0<\/code>–<code>P1.3<\/code> là LED (chân 0 = sáng); <code>P1.4<\/code> là rơ-le qua transistor NPN có điện trở kéo lên (chân 1 = bật); <code>P1.5<\/code> là còi qua transistor PNP (chân 0 = kêu); <code>P1.6<\/code>, <code>P1.7<\/code> bỏ trống, chốt phải giữ 1. Ô <code>30H<\/code> chứa trạng thái logic: bit <i>k<\/i> = 1 nghĩa là tải ở P1.<i>k<\/i> cần <b>bật<\/b>. Viết tầng driver: xuất ra <code>P1<\/code> đúng mức chân, <code>30H<\/code> giữ nguyên. Bit 6, 7 của 30H nếu bằng 1 thì chân tương ứng xuống 0 (theo cùng mặt nạ). Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 11H<\/code> (LED0, rơ-le) → <code>P1 = FEH<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,30H                   ; trạng thái logic\n        CPL     A                       ; coi mọi tải là tích cực mức thấp\n        MOV     P1,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":17}},"expect":{"iram":{"0x30":17},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":0}},"expect":{"iram":{"0x30":0},"ports":{"P1":239}}},{"setup":{"iram":{"0x30":32}},"expect":{"iram":{"0x30":32},"ports":{"P1":207}}},{"setup":{"iram":{"0x30":16}},"expect":{"iram":{"0x30":16},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":63}},"expect":{"iram":{"0x30":63},"ports":{"P1":208}}},{"setup":{"iram":{"0x30":197}},"expect":{"iram":{"0x30":197},"ports":{"P1":42}}}]},"hints":["Lập mặt nạ cực tính: bit = 1 ở những chân tích cực mức thấp hoặc bỏ trống, bit = 0 ở chân tích cực mức cao.","Chân = logic XOR mặt nạ. Code mẫu đảo cả byte, tức là coi mọi tải đều tích cực mức thấp.","Chỉ ba bước: đọc, áp mặt nạ cực tính bằng XOR, ghi ra cổng. Hằng hệ 16 bắt đầu bằng chữ cần số 0 đứng trước."],"why":"Mặt nạ cực tính gom mọi hiểu biết về mạch ngoài vào một hằng số: đổi bo chỉ phải đổi hằng số đó, phần logic phía trên không đổi. Với bo này mặt nạ là 1110 1111B = EFH; code mẫu dùng CPL A (mặt nạ FFH) nên rơ-le ở P1.4 bị đảo ngược."},{"t":"Driver LED có giới hạn dòng","d":"<p>8 LED ở P1 sáng khi chân = 0, mỗi LED khoảng 4,6 mA (giả định của bài, tính ở mục 23.1). Để tổng dòng kéo vào cổng P1 không vượt 15 mA (giới hạn mỗi cổng trong ghi chú của datasheet — PENDING đối chiếu), driver chỉ cho bật tối đa <b>3<\/b> LED. Ô <code>30H<\/code> = mẫu logic (bit = 1: LED cần sáng). Viết driver: ghi vào <code>31H<\/code> số LED được yêu cầu (số bit 1 của 30H). Nếu số đó ≤ 3: xuất mẫu ra P1 (LED tích cực mức thấp) và ghi <code>32H = 00H<\/code>. Nếu ≥ 4: tắt hết (<code>P1 = FFH<\/code>) và ghi <code>32H = 01H<\/code> (báo lỗi). <code>30H<\/code> giữ nguyên. Chỉ một lệnh <code>SJMP $<\/code> ở cuối.<\/p><p>Ví dụ: <code>30H = 01H<\/code> → <code>31H = 01H<\/code>, <code>32H = 00H<\/code>, <code>P1 = FEH<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,30H\n        MOV     R7,#8\n        MOV     R2,#00H\nDEM:    RLC     A                       ; bit cao nhất vào CY\n        JNC     KHONG\n        INC     R2                      ; thêm một LED\nKHONG:  DJNZ    R7,DEM\n        MOV     31H,R2\n        MOV     32H,#00H\n        MOV     A,30H\n        CPL     A\n        MOV     P1,A                    ; xuất luôn, chưa kiểm tra dòng\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x32":85}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":0},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":0,"0x32":85}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":7,"0x32":85}},"expect":{"iram":{"0x30":7,"0x31":3,"0x32":0},"ports":{"P1":248}}},{"setup":{"iram":{"0x30":15,"0x32":85}},"expect":{"iram":{"0x30":15,"0x31":4,"0x32":1},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":255,"0x32":85}},"expect":{"iram":{"0x30":255,"0x31":8,"0x32":1},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":133,"0x32":85}},"expect":{"iram":{"0x30":133,"0x31":3,"0x32":0},"ports":{"P1":122}}},{"setup":{"iram":{"0x30":153,"0x32":85}},"expect":{"iram":{"0x30":153,"0x31":4,"0x32":1},"ports":{"P1":255}}}]},"hints":["Đếm bit 1: lặp 8 lần RLC A, mỗi lần CY = 1 thì tăng một thanh ghi đếm (JNC bỏ qua lệnh tăng).","So số đếm với 4: CJNE Rn,#4,nhãn đặt CY = 1 khi Rn &lt; 4; hoặc CLR C rồi SUBB A,#4.","Ghi trước giá trị “an toàn” (P1 = FFH, 32H = 01H), chỉ nhánh hợp lệ mới ghi đè — chương trình có một lối ra duy nhất."],"why":"Tầng driver là chỗ duy nhất biết giới hạn điện của phần cứng, nên kiểm tra dòng đặt ở đây chứ không rải trong logic. Code mẫu xuất thẳng mẫu ra cổng, bộ thử 4, 5, 7 (≥ 4 LED) bắt lỗi. Viết giá trị an toàn trước rồi mới mở là thói quen tốt cho driver tải."},{"t":"Cập nhật 4 LED không đụng chân khác, ≤ 8 chu kỳ","d":"<p>Trên P1: <code>P1.0<\/code>–<code>P1.3<\/code> là 4 LED (chân 0 = sáng) do driver này quản lý; <code>P1.4<\/code>–<code>P1.7<\/code> thuộc driver khác, <b>chốt<\/b> của chúng phải giữ nguyên (lúc chạy có thể bằng bất kỳ giá trị nào, và tải ngoài có thể đang ghìm chân của chúng xuống 0). Ô <code>30H<\/code>: nửa thấp là mẫu logic 4 LED (bit = 1: sáng), nửa cao là rác phải bỏ qua. Cập nhật chốt P1.0–P1.3 theo mẫu. Yêu cầu: không quá <b>8 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và không quá <b>12 byte<\/b>.<\/p><p>Ví dụ: chốt P1 = <code>FFH<\/code>, <code>30H = 01H<\/code> → chốt <code>P1 = FEH<\/code>. Code mẫu đọc <b>chân<\/b> P1 nên sai khi có tải ghìm chân, và tốn 10 chu kỳ, 15 byte.<\/p>","start":"        ORG     0000H\n        MOV     A,P1                    ; đọc P1 để giữ nửa cao\n        ANL     A,#0F0H\n        MOV     R2,A\n        MOV     A,30H\n        CPL     A                       ; LED tích cực mức thấp\n        ANL     A,#0FH\n        ORL     A,R2\n        MOV     P1,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1},"regs":{"P1":255},"pins":{"P1":255}},"expect":{"iram":{"0x30":1},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":10},"regs":{"P1":95},"pins":{"P1":255}},"expect":{"iram":{"0x30":10},"ports":{"P1":85}}},{"setup":{"iram":{"0x30":5},"regs":{"P1":243},"pins":{"P1":239}},"expect":{"iram":{"0x30":5},"ports":{"P1":250}}},{"setup":{"iram":{"0x30":240},"regs":{"P1":60},"pins":{"P1":255}},"expect":{"iram":{"0x30":240},"ports":{"P1":63}}},{"setup":{"iram":{"0x30":0},"regs":{"P1":0},"pins":{"P1":255}},"expect":{"iram":{"0x30":0},"ports":{"P1":15}}},{"setup":{"iram":{"0x30":54},"regs":{"P1":201},"pins":{"P1":127}},"expect":{"iram":{"0x30":54},"ports":{"P1":201}}}],"maxCyc":8,"maxBytes":12},"hints":["Không được đọc chân P1 (MOV A,P1): chân bị tải ghìm sẽ chép 0 vào chốt của driver khác. Chỉ dùng lệnh đọc–sửa–ghi vào P1.","Hai bước đọc–sửa–ghi: trước hết đặt nửa thấp của chốt = 1111 (ORL P1,#…), sau đó AND với một byte có nửa cao = 1111 và nửa thấp = mẫu đã đảo.","Byte để AND tạo được từ 30H bằng một phép đảo và một phép OR với nửa cao; rồi AND thẳng vào cổng."],"why":"Lệnh đọc–sửa–ghi vào cổng đọc chốt, nên chốt của driver khác giữ nguyên dù chân của nó đang bị tải ghìm. Lời giải gồm hai lệnh đọc–sửa–ghi vào P1 kẹp ba lệnh tạo mặt nạ trong A: 6 + 2 = 8 chu kỳ, 12 byte. Giữa hai lệnh, 4 LED tắt trong 3 chu kỳ máy (3 µs) — không thấy bằng mắt, nhưng phải ghi vào tài liệu driver nếu tải nhạy với xung ngắn."}]);

makeQuiz("quiz23","score23",[{"q": "LED đỏ nối từ 5 V qua R vào chân (sáng khi chân = 0). Giả định V_F = 2,0 V, V_OL = 0,4 V, muốn khoảng 5 mA. Chọn R chuẩn nào hợp lý?", "o": ["560 Ω (≈ 4,6 mA)", "100 Ω (≈ 26 mA)", "56 kΩ (≈ 0,05 mA)", "Không cần điện trở"], "a": 0, "e": "R = (5 − 2,0 − 0,4) / 5 mA = 520 Ω, giá trị chuẩn gần nhất phía trên là 560 Ω. 100 Ω cho dòng vượt giới hạn mỗi chân; 56 kΩ làm LED gần như tắt; không có điện trở thì dòng chỉ bị chân và LED giới hạn — sai thiết kế."}, {"q": "Vì sao trên bo 8051 hay nối còi qua transistor PNP (chân = 0 thì kêu) thay vì NPN không có kéo lên ngoài?", "o": ["NPN không dẫn được dòng 30 mA", "PNP làm còi kêu to hơn", "Chân kéo xuống mạnh, kéo lên rất yếu; PNP còn giữ còi tắt khi reset", "8051 không xuất được mức 1"], "a": 2, "e": "PNP dùng chiều nhận dòng mạnh của chân, và sau reset chân = 1 nên còi tắt. NPN cần dòng chảy ra từ chân — kéo lên trong quá yếu nên phải thêm kéo lên ngoài, và khi đó tải bật ngay lúc reset."}, {"q": "Vòng tạo âm có đúng 250 chu kỳ máy giữa hai lần CPL P1.0, thạch anh 12 MHz. Tần số âm là bao nhiêu?", "o": ["2 000 Hz", "4 000 Hz", "1 000 Hz", "250 Hz"], "a": 0, "e": "Nửa chu kỳ 250 µs → chu kỳ 500 µs → 2 000 Hz. 4 000 Hz là nhầm nửa chu kỳ thành cả chu kỳ."}, {"q": "Mặt nạ cực tính là DFH. Phần logic muốn bật đúng tải ở P1.5 (logic 20H). Driver ghi ra P1 giá trị nào?", "o": ["DFH", "FFH", "20H", "00H"], "a": 1, "e": "Chân = logic XOR mặt nạ = 20H XOR DFH = FFH: P1.5 = 1 là bật vì tải này tích cực mức cao, mọi tải tích cực mức thấp nhận 1 nên tắt."}, {"q": "Phần LED dùng MOV P1,#0FEH để bật LED0 trong khi phần còi đang dùng P1.7. Sửa thế nào cho đúng nguyên tắc sở hữu chân?", "o": ["Ghi MOV P1,#7EH cho đúng cả còi", "Đọc MOV A,P1 rồi sửa và ghi lại", "Chuyển còi sang P0", "Dùng CLR P1.0 (hoặc ANL P1,#0FEH) để chỉ đổi bit của mình"], "a": 3, "e": "Lệnh đọc–sửa–ghi chỉ đổi bit được chọn và đọc chốt. Ghi 7EH buộc phần LED biết trạng thái còi (phá vỡ tách lớp); MOV A,P1 đọc chân, dễ chép mức bị tải ghìm vào chốt."}]);

